import{_ as s,o as i,c as r,a3 as t}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Guide d’utilisation","description":"","frontmatter":{},"headers":[],"relativePath":"fr/projects/logic-studio/user-guide.md","filePath":"fr/projects/logic-studio/user-guide.md","lastUpdated":1794859109000}'),o={name:"fr/projects/logic-studio/user-guide.md"};function n(a,e,l,u,d,c){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="guide-d-utilisation" tabindex="-1">Guide d’utilisation <a class="header-anchor" href="#guide-d-utilisation" aria-label="Permalink to &quot;Guide d’utilisation&quot;">​</a></h1><p>Ce guide s’adresse aux débutants. Ouvre HA Logic Studio Pro dans Home Assistant, sélectionne <strong>Nouveau projet</strong>, puis choisis un éditeur et un nom. Pour les exemples, crée un interrupteur dans <strong>Paramètres → Appareils et services → Entrées</strong>. Les exemples utilisent <code>input_boolean.studio_test</code>. Utilise l’identifiant réel de ton entrée.</p><h2 id="quel-editeur-choisir" tabindex="-1">Quel éditeur choisir ? <a class="header-anchor" href="#quel-editeur-choisir" aria-label="Permalink to &quot;Quel éditeur choisir ?&quot;">​</a></h2><ul><li><strong>Plan fonctionnel</strong> pour les signaux, minuteries et compteurs sur un canevas.</li><li><strong>Rules</strong> pour les règles SI → ALORS ou SINON.</li><li><strong>Blocks A</strong> pour assembler des automatisations Home Assistant à partir de blocs.</li><li><strong>Blocks JS</strong> pour assembler des scripts et importer des projets ioBroker.</li><li><strong>JavaScript</strong> ou <strong>TypeScript</strong> pour écrire des scripts.</li><li><strong>HA-YAML</strong> pour modifier, vérifier et visualiser des automatisations et des scripts.</li></ul><h2 id="commandes-communes" tabindex="-1">Commandes communes <a class="header-anchor" href="#commandes-communes" aria-label="Permalink to &quot;Commandes communes&quot;">​</a></h2><ul><li><strong>Enregistrer</strong> conserve les modifications. Le bouton orange signale des modifications en attente. Le bouton gris indique que tout est enregistré.</li><li><strong>Annuler</strong> abandonne les modifications depuis le dernier enregistrement et restaure la version enregistrée.</li><li><strong>Test</strong> utilise la simulation dans les éditeurs de scripts. Dans le plan fonctionnel, tu peux basculer les entrées simulées.</li><li><strong>Play</strong> démarre la version enregistrée dans le moteur d’exécution pour le plan fonctionnel, Blocks JS, JavaScript et TypeScript. Les actions HA autorisées peuvent y modifier les entités réelles. <strong>Stop</strong> arrête l’exécution.</li><li><strong>Vérifier</strong> indique les problèmes avant l’export ou l’exécution. <strong>Exporter</strong> crée un fichier que tu peux utiliser dans Home Assistant.</li><li>Le <strong>mode expert</strong> du menu du projet affiche des outils supplémentaires. Le <strong>journal</strong> affiche les résultats et les erreurs du projet ouvert.</li></ul><h2 id="editeurs" tabindex="-1">Éditeurs <a class="header-anchor" href="#editeurs" aria-label="Permalink to &quot;Éditeurs&quot;">​</a></h2><ul><li><a href="./user-guide/function-plan">Plan fonctionnel</a></li><li><a href="./user-guide/rules">Rules</a></li><li><a href="./user-guide/blocks-a">Blocks A</a></li><li><a href="./user-guide/blocks-js">Blocks JS</a></li><li><a href="./user-guide/javascript">JavaScript</a></li><li><a href="./user-guide/typescript">TypeScript</a></li><li><a href="./user-guide/ha-yaml">HA-YAML</a></li><li><a href="./user-guide/feedback">Signaler un problème et contribuer</a></li></ul>',8)])])}const m=s(o,[["render",n]]);export{g as __pageData,m as default};
